#include <iostream>
#include <memory>
#include <vector>
#include <algorithm>

template <typename T1, typename D1, typename T2, typename D2>
bool operator<(const std::unique_ptr<T1, D1>& x, const std::unique_ptr<T2, D2>& y) {
    if (x && y) {
        return *x < *y;
    }
    return x != nullptr && y == nullptr;
}

int main() {
    auto ptr1 = std::make_unique<int>(10);
    auto ptr2 = std::make_unique<int>(20);
    auto ptr3 = std::make_unique<int>(5);
    std::vector<std::unique_ptr<int>> vec;
    vec.push_back(std::move(ptr1));
    vec.push_back(std::move(ptr2));
    vec.push_back(std::move(ptr3));
    std::sort(vec.begin(), vec.end());
    for (const auto& p : vec) {
        std::cout << *p << ' ';
    }
    return 0;
}
